    const logged = [];
    const originalLog = console.log;
    const originalError = console.error;
    const originalStdoutWrite = process.stdout.write.bind(process.stdout);
    const originalStderrWrite = process.stderr.write.bind(process.stderr);
    console.log = (...args) => { logged.push(args.join(' ')); };
    console.error = (...args) => { logged.push(args.join(' ')); };
    // Agents may log through an injectable writer straight to the streams
    // instead of console.*. Capture-then-pass-through: the bytes always reach
    // the stream untouched, so the grader's own ECC_EVAL_SCORE line (emitted
    // via process.stdout.write) can never be swallowed or corrupted.
    const tap = write => (chunk, encoding, callback) => {
      try { logged.push(Buffer.isBuffer(chunk) ? chunk.toString('utf8') : String(chunk)); } catch { /* capture must never break a write */ }
      return write(chunk, encoding, callback);
    };
    process.stdout.write = tap(originalStdoutWrite);
    process.stderr.write = tap(originalStderrWrite);
